function item(topic, level, slug, prompt, options, answer, explanation, figure) {
  return {
    id: 'biology-extra-' + slug,
    bank: 'biology-' + topic,
    level,
    prompt,
    options,
    answer,
    explanation,
    ...(figure && { figure }),
  };
}

function part(label, unit, answer, tolerance = 0) {
  return { label, unit, answer, tolerance };
}

function calculation(topic, slug, prompt, parts, explanation, figure) {
  return {
    id: 'biology-extra-' + slug,
    bank: 'biology-' + topic,
    level: 'challenge',
    prompt,
    parts,
    explanation,
    figure,
  };
}

function table(caption, headers, rows) {
  return { caption, headers, rows };
}

function diagram(caption, alt, viewBox, shapes) {
  return {
    caption,
    alt,
    svg: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="' + viewBox + '" aria-hidden="true"><g font-family="system-ui, sans-serif" font-size="16" fill="#182d41">' + shapes + '</g></svg>',
  };
}

